// Parser: Tokens → Abstract Syntax Tree
// Parses FV-Lang token stream into an AST
// Security hardened with recursion depth limits

use crate::{lexer::Token, ast::*, CompileError};

// Security limits
const MAX_PARSE_DEPTH: usize = 1000;  // 최대 파싱 깊이
const MAX_TOKENS: usize = 100_000;    // 최대 토큰 수

pub struct Parser {
    tokens: Vec<Token>,
    pos: usize,
    errors: Vec<CompileError>,  // ✅ 에러 수집
}

impl Parser {
    /// 토큰 배열 크기 검증과 함께 파서 생성
    pub fn new(tokens: Vec<Token>) -> Result<Self, CompileError> {
        if tokens.len() > MAX_TOKENS {
            return Err(CompileError::ParserError(format!(
                "토큰 수가 너무 많음: {} (최대 {})",
                tokens.len(),
                MAX_TOKENS
            )));
        }

        Ok(Parser {
            tokens,
            pos: 0,
            errors: Vec::new(),
        })
    }

    /// 에러 복구: 다음 동기화 포인트까지 스킵
    fn synchronize(&mut self) {
        self.advance();

        while !self.is_at_end() {
            if self.tokens.get(self.pos.saturating_sub(1)) == Some(&Token::Semicolon) {
                return;
            }

            match self.peek() {
                Token::Fn | Token::Type | Token::Let | Token::If | Token::Return => return,
                Token::RBrace | Token::Eof => return,
                _ => self.advance(),
            }
        }
    }

    pub fn parse(mut self) -> Result<Program, CompileError> {
        let mut definitions = Vec::new();
        let mut statements = Vec::new();

        while !self.is_at_end() {
            match self.peek() {
                Token::Fn => {
                    match self.parse_function() {
                        Ok(Some(def)) => definitions.push(def),
                        Ok(None) => break,
                        Err(_) => { self.synchronize(); }
                    }
                }
                Token::Type => {
                    match self.parse_type_def() {
                        Ok(Some(def)) => definitions.push(def),
                        Ok(None) => break,
                        Err(_) => { self.synchronize(); }
                    }
                }
                Token::Eof => break,
                // 최상위 구문 (let, 표현식 등)
                _ => {
                    match self.parse_statement() {
                        Ok(stmt) => statements.push(stmt),
                        Err(_) => { self.synchronize(); }
                    }
                }
            }

