		if err != nil {
			t.Fatalf("New failed for %s: %v", kw.text, err)
		}

		tokens, err := lex.Tokenize()
		if err != nil {
			t.Fatalf("Tokenize failed for %s: %v", kw.text, err)
		}

		if tokens[0].Type != kw.typ {
			t.Errorf("Expected %v for '%s', got %v", kw.typ, kw.text, tokens[0].Type)
		}
	}
}

